CREATE TABLE IF NOT EXISTS cars (id TEXT PRIMARY KEY, plate TEXT, make TEXT, model TEXT, trim TEXT, year INTEGER, location TEXT, first_registration TEXT, current_km INTEGER, last_test_km INTEGER, last_test_date TEXT, asking_price INTEGER, benchmark_price INTEGER, benchmark_source TEXT, yad2_low INTEGER, yad2_high INTEGER, original_ownership TEXT, hand_count INTEGER, ownership_history TEXT, test_expiry TEXT, insurance_claims TEXT, service_history TEXT, cabin_fit TEXT, tires TEXT, db_structural_damage TEXT NOT NULL DEFAULT 'unknown', db_total_loss TEXT NOT NULL DEFAULT 'unknown', db_lien TEXT NOT NULL DEFAULT 'unknown', db_seller_refuses TEXT NOT NULL DEFAULT 'unknown', gov_structural_change INTEGER, notes TEXT, listing_url TEXT, seller_name TEXT, seller_phone TEXT, status TEXT NOT NULL DEFAULT 'considering', field_sources TEXT NOT NULL DEFAULT '{}', score_min INTEGER, score_max INTEGER, rating TEXT, coverage INTEGER, date_added TEXT NOT NULL, updated_at TEXT NOT NULL, model_notes TEXT, price_estimate TEXT, registry TEXT);
CREATE INDEX IF NOT EXISTS idx_cars_status ON cars (status);
CREATE INDEX IF NOT EXISTS idx_cars_score_max ON cars (score_max);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT, updated_at TEXT NOT NULL);
